    'Тема': 'Topic',
    'Вкажи пошту акаунта. Дані на телефоні стираються в Налаштуваннях → «Стерти всі дані»; дані на сервері (профіль, дописи, повідомлення) видалимо за твоїм зверненням.': 'Enter your account email. Data on the phone is erased in Settings → “Erase all data”; data on the server (profile, posts, messages) will be deleted at your request.',
