    'Вага стоїть на місці — щотижня додається підхід і скорочується відпочинок. 6 тижнів.': 'The weight stays the same — each week a set is added and the rest gets shorter. 6 weeks.',
    'Тиждень 1: запамʼятай, скільки відпочиваєш між підходами (наприклад, 70 с).': 'Week 1: note how long you rest between sets (for example, 70 s).',
    'Щотижня відпочинок на 5 с коротший, а в ще одній вправі дня — +1 підхід (тиждень 2 — у першій, тиждень 3 — у перших двох… тиждень 6 — у всіх по 5 підходів).': 'Each week the rest is 5 s shorter, and in one more exercise of the day — +1 set (week 2 — in the first, week 3 — in the first two… week 6 — 5 sets in all).',
    'Тренування має вкластися в той самий час, що й на першому тижні (близько 45 хв).': 'The workout should fit into the same time as in the first week (about 45 min).',
    'Після 6 тижнів: знову по 4 підходи, але додай по вправі: жим ногами, тягу верхнього блока, розведення гантелей.': 'After 6 weeks: 4 sets again, but add an exercise to each: leg press, lat pulldown, dumbbell flyes.',
