    'Два тренування чергуються через день: A — спина й груди, B — ноги, плечі й руки.': 'Two workouts alternate every other day: A — back and chest, B — legs, shoulders and arms.',
    'A і B чергуються: тиждень 1 — A, B, A; тиждень 2 — B, A, B.': 'A and B alternate: week 1 — A, B, A; week 2 — B, A, B.',
    'A: тяга й жим по черзі, 3 кола. B: чотири вправи по колу, 2–3 кола.': 'A: row and press in turn, 3 circuits. B: four exercises in a circuit, 2–3 circuits.',
    'Повторень у схемі немає — бери 8–12 з вагою, де останні 2 даються важко.': 'The scheme has no fixed reps — take 8–12 with a weight where the last 2 are hard.',
