    'Фулбаді для жінок — початок': 'Full body for women — beginner',
    'Пʼять вправ на все тіло тричі на тиждень, багато повторень із легкою вагою.': 'Five full-body exercises three times a week, lots of reps with light weight.',
    'Тест: якщо робиш 30 віджимань з колін з чистою технікою — переходь на другий рівень.': 'Test: if you can do 30 knee push-ups with clean technique — move on to the second level.',
    'Вага — така, щоб останні 2–3 повторення давалися важко, але без ривків.': 'Use a weight where the last 2–3 reps are hard, but without jerking.',
