    'Фулбаді для жінок — другий рівень': 'Full body for women — second level',
    'Шість вправ: прес, ноги, спина й руки. Для тих, хто робить 30 віджимань з колін.': 'Six exercises: abs, legs, back and arms. For those who can do 30 knee push-ups.',
    'Коли в усіх підходах виходить 15 повторень — трохи додай вагу.': 'When you get 15 reps in all sets — add a little weight.',
    'Фулбаді — другий рівень': 'Full body — second level',
