    'Звикання до навантаження: скручування, присідання й віджимання. Без інвентарю.': 'Getting used to the load: crunches, squats and push-ups. No equipment.',
    'Повторюй, коли мʼязи повністю перестали боліти після минулого разу (спочатку це 3–7 днів).': 'Repeat when your muscles have fully stopped aching from last time (at first that\'s 3–7 days).',
    'Коли біль минає за 1–2 дні — переходь на середній рівень.': 'When the soreness goes away in 1–2 days — move on to the intermediate level.',
