    'Помилка, ідея, питання про оплату чи прохання видалити дані — напиши, ми прочитаємо кожне звернення.': 'Błąd, pomysł, pytanie o płatność lub prośba o usunięcie danych — napisz, przeczytamy każde zgłoszenie.',
    'Тема': 'Temat',
    'Вкажи пошту акаунта. Дані на телефоні стираються в Налаштуваннях → «Стерти всі дані»; дані на сервері (профіль, дописи, повідомлення) видалимо за твоїм зверненням.': 'Podaj e-mail konta. Dane w telefonie usuwa się w Ustawieniach → „Usuń wszystkie dane”; dane na serwerze (profil, posty, wiadomości) usuniemy na twoją prośbę.',
    'Повідомлення': 'Wiadomość',
