    'Пошта для відповіді (необовʼязково)': 'E-mail do odpowiedzi (opcjonalnie)',
    'Разом зі зверненням надсилаються лише версія застосунку й мова — без твоїх тренувань.': 'Razem ze zgłoszeniem wysyłamy tylko wersję aplikacji i język — bez twoich treningów.',
    'Чекають відправки': 'Czeka na wysłanie',
