    'Низ — легкий': 'Dół — lekki',
    '12–20 або згинання ніг лежачи': '12–20 lub uginanie nóg leżąc',
    'Відведення руки з нижнього блока': 'Odwodzenie ramienia na wyciągu dolnym',
    '12–20, за бажанням': '12–20, opcjonalnie',
