    'Жим штанги лежачи до шиї': 'Wyciskanie sztangi leżąc do szyi (guillotine press)',
    '12–20, легка вага': '12–20, lekki ciężar',
    'Кросовер': 'Krzyżowanie linek wyciągu (cable crossover)',
    'Розгинання рук на блоці': 'Prostowanie ramion na wyciągu',
    'Спліт на 5 днів із легким тижнем': 'Split na 5 dni z lekkim tygodniem',
    'Кожен день — одна група мʼязів. Тиждень важкий, тиждень легкий (40–60 % ваги), далі по колу з трохи більшою вагою.': 'Każdego dnia jedna partia mięśni. Tydzień ciężki, tydzień lekki (40–60 % ciężaru), potem od początku z nieco większym ciężarem.',
    'Цикл — 2 тижні: важкий тиждень (Пн спина, Вт груди, Ср ноги, Чт плечі, Пт руки), потім легкий.': 'Cykl trwa 2 tygodnie: tydzień ciężki (Pon plecy, Wt klatka, Śr nogi, Czw barki, Pt ręce), potem lekki.',
    'У легкий тиждень постав у Календарі легкі тренування: Пн і Вт — 40 % робочої ваги, Чт і Пт — 60 %.': 'W lekkim tygodniu ustaw w Kalendarzu lekkie treningi: Pon i Wt — 40 % ciężaru roboczego, Czw i Pt — 60 %.',
    'Прогрес: дивись у щоденнику результат 2 тижні тому. Перший підхід — +2 % ваги (або +1–2 кг), останній — та сама вага, але на 1–2 повторення більше.': 'Progres: sprawdź w dzienniku wynik sprzed 2 tygodni. Pierwsza seria — +2 % ciężaru (lub +1–2 kg), ostatnia — ten sam ciężar, ale o 1–2 powtórzenia więcej.',
    'В ізольованих вправах (розведення, махи) вагу не додавай — лише повторення.': 'W ćwiczeniach izolowanych (rozpiętki, unoszenie bokiem) nie zwiększaj ciężaru — tylko powtórzenia.',
    'Наприкінці дня — 7 коротких підходів по 6–8 повторень з 60–70 % ваги, паузи 15–30 с: на «накачку».': 'Na koniec dnia — 7 krótkich serii po 6–8 powtórzeń z 60–70 % ciężaru, przerwy 15–30 s: na „pompę”.',
    'Тяга гантелі однією рукою': 'Wiosłowanie hantlem jednorącz',
    '4 × 6–12 на кожну руку': '4 × 6–12 na każdą rękę',
    'Тяга горизонтального блока': 'Wiosłowanie na wyciągu dolnym siedząc',
    '3 × 6–12, на відчуття мʼяза': '3 × 6–12, z czuciem mięśnia',
