    'Молоткові згинання': 'Uginanie młotkowe',
    'Французький жим гантелі з-за голови': 'Wyciskanie francuskie hantla zza głowy',
    'Легкий: спина й ноги (40 %)': 'Lekki: plecy i nogi (40 %)',
    '8 × 10–12, 40 % ваги, 35 с відпочинку': '8 × 10–12, 40 % ciężaru, 35 s odpoczynku',
