    'Обʼєм замість ваги, 3 дні': 'Objętość zamiast ciężaru, 3 dni',
    'Вага стоїть на місці — щотижня додається підхід і скорочується відпочинок. 6 тижнів.': 'Ciężar stoi w miejscu — co tydzień dochodzi seria i skraca się odpoczynek. 6 tygodni.',
    'Тиждень 1: запамʼятай, скільки відпочиваєш між підходами (наприклад, 70 с).': 'Tydzień 1: zapamiętaj, ile odpoczywasz między seriami (na przykład 70 s).',
    'Щотижня відпочинок на 5 с коротший, а в ще одній вправі дня — +1 підхід (тиждень 2 — у першій, тиждень 3 — у перших двох… тиждень 6 — у всіх по 5 підходів).': 'Co tydzień odpoczynek jest krótszy o 5 s, a w jeszcze jednym ćwiczeniu dnia — +1 seria (tydzień 2 — w pierwszym, tydzień 3 — w pierwszych dwóch… tydzień 6 — we wszystkich po 5 serii).',
    'Тренування має вкластися в той самий час, що й на першому тижні (близько 45 хв).': 'Trening ma się zmieścić w tym samym czasie co w pierwszym tygodniu (około 45 min).',
    'Після 6 тижнів: знову по 4 підходи, але додай по вправі: жим ногами, тягу верхнього блока, розведення гантелей.': 'Po 6 tygodniach: znowu po 4 serie, ale dodaj do każdego po ćwiczeniu: wyciskanie nogami, ściąganie drążka wyciągu górnego, rozpiętki z hantlami.',
