    'Два тренування чергуються через день: A — спина й груди, B — ноги, плечі й руки.': 'Dwa treningi występują naprzemiennie co drugi dzień: A — plecy i klatka, B — nogi, barki i ręce.',
    'A і B чергуються: тиждень 1 — A, B, A; тиждень 2 — B, A, B.': 'A i B występują naprzemiennie: tydzień 1 — A, B, A; tydzień 2 — B, A, B.',
    'A: тяга й жим по черзі, 3 кола. B: чотири вправи по колу, 2–3 кола.': 'A: wiosłowanie i wyciskanie naprzemiennie, 3 obwody. B: cztery ćwiczenia w obwodzie, 2–3 obwody.',
    'Повторень у схемі немає — бери 8–12 з вагою, де останні 2 даються важко.': 'W schemacie nie ma powtórzeń — rób 8–12 z ciężarem, przy którym ostatnie 2 są trudne.',
