    'Фулбаді для жінок — початок': 'FBW dla kobiet — początek',
    'Пʼять вправ на все тіло тричі на тиждень, багато повторень із легкою вагою.': 'Pięć ćwiczeń na całe ciało trzy razy w tygodniu, dużo powtórzeń z lekkim ciężarem.',
    'Тест: якщо робиш 30 віджимань з колін з чистою технікою — переходь на другий рівень.': 'Test: jeśli robisz 30 pompek z kolan z czystą techniką — przejdź na drugi poziom.',
    'Вага — така, щоб останні 2–3 повторення давалися важко, але без ривків.': 'Ciężar taki, żeby ostatnie 2–3 powtórzenia były trudne, ale bez szarpania.',
