    'Шість вправ: прес, ноги, спина й руки. Для тих, хто робить 30 віджимань з колін.': 'Sześć ćwiczeń: brzuch, nogi, plecy i ręce. Dla tych, którzy robią 30 pompek z kolan.',
    'Коли в усіх підходах виходить 15 повторень — трохи додай вагу.': 'Gdy we wszystkich seriach wychodzi 15 powtórzeń — trochę zwiększ ciężar.',
