    'Повне: розминка → важка вправа на 6–12 повторень → дві вправи по 30 с роботи й 30 с відпочинку, 3 рази.': 'Pełny: rozgrzewka → ciężkie ćwiczenie na 6–12 powtórzeń → dwa ćwiczenia po 30 s pracy i 30 s odpoczynku, 3 razy.',
    'Стало легко — ускладнюй: віджимання з ногами на стільці, повільніше скручування.': 'Zrobiło się łatwo — utrudniaj: pompki z nogami na krześle, wolniejsze brzuszki.',
