    'Ірина': 'Iryna',
    "Їжа на 3 дні за годину: крупа, запечене м’ясо, овочі. Рецепти з калоріями — у розділі «Рецепти».": 'Jedzenie na 3 dni w godzinę: kasza, pieczone mięso, warzywa. Przepisy z kaloriami — w sekcji „Przepisy”.',
    'Андрій': 'Andrii',
    'Атлет': 'Atleta',
    'Вода: 30–35 мл на кг ваги, у дні тренувань більше. Спрага — вже запізнення.': 'Woda: 30–35 ml na kg masy ciała, w dni treningowe więcej. Pragnienie to już spóźnienie.',
    'Відкрити рецепти': 'Otwórz przepisy',
    'Відпочинок між підходами: 1–2 хв на легкі вправи, 2–4 хв на важкі базові. Таймер у застосунку підкаже сам.': 'Odpoczynek między seriami: 1–2 min przy lekkich ćwiczeniach, 2–4 min przy ciężkich podstawowych. Timer w aplikacji sam podpowie.',
    'Вінниця': 'Vinnytsia',
    'Гантелі, гумки й килимок — цього досить для повноцінного тренування вдома.': 'Hantle, gumy i mata — to wystarczy na pełnowartościowy trening w domu.',
    'День спини. Станова 140×3 — новий рекорд 🏆': 'Dzień pleców. Martwy ciąg 140×3 — nowy rekord 🏆',
