    'Махи гирею: рух іде від стегон, не від рук.': 'Machy kettlebell: ruch wychodzi z bioder, nie z rąk.',
    'Нарешті 60 кг у присіді! Пів року роботи 🔥': 'Wreszcie 60 kg w przysiadzie! Pół roku pracy 🔥',
    'Новенькі в групі — перше заняття завжди з легкою вагою і відео техніки.': 'Nowi w grupie — pierwsze zajęcia zawsze z lekkim ciężarem i filmem z techniką.',
