    'Офіційний акаунт': 'Oficjalne konto',
    'Офіційний акаунт Gym Log: 100 рецептів з калоріями й БЖВ — у розділі «Рецепти».': 'Oficjalne konto Gym Log: 100 przepisów z kaloriami i makroskładnikami — w sekcji „Przepisy”.',
    'Офіційний акаунт Gym Log: техніка вправ, відновлення, прості плани для залу й дому.': 'Oficjalne konto Gym Log: technika ćwiczeń, regeneracja, proste plany na siłownię i dom.',
    'Офіційні акаунти': 'Oficjalne konta',
    'Планка: тіло — одна лінія, сідниці напружені, дихай рівно. Краще 3×30 с правильно, ніж 2 хв із провисанням.': 'Deska: ciało w jednej linii, pośladki napięte, oddychaj równo. Lepiej 3×30 s poprawnie niż 2 min z opadającymi biodrami.',
    'Приклад профілю': 'Przykładowy profil',
    'Приклад профілю атлета: пауерліфтинг-аматор, станова — моя любов.': 'Przykładowy profil atlety: amator trójboju siłowego, martwy ciąg to moja miłość.',
    'Приклад профілю атлета: пів року в залі, ціль — присід 70 кг.': 'Przykładowy profil atlety: pół roku na siłowni, cel — przysiad 70 kg.',
    'Приклад профілю тренерки: жіночі групи, техніка з нуля, без страху перед залізом 🙌': 'Przykładowy profil trenerki: grupy dla kobiet, technika od podstaw, bez strachu przed żelazem 🙌',
    'Приклад профілю — так виглядатиме сторінка справжньої людини': 'Przykładowy profil — tak będzie wyglądać strona prawdziwej osoby',
    'Приклад профілю: мобільність, розтяжка, відновлення після травм.': 'Przykładowy profil: mobilność, rozciąganie, powrót do formy po kontuzjach.',
    'Приклад профілю: функціональний тренінг і кросфіт, перше заняття безкоштовно 🔥': 'Przykładowy profil: trening funkcjonalny i crossfit, pierwsze zajęcia za darmo 🔥',
    'Приклади профілів': 'Przykładowe profile',
    'Присід: стопи на ширині плечей, коліна йдуть за носками, спина нейтральна. Глибина — до паралелі або нижче, якщо дозволяє мобільність.': 'Przysiad: stopy na szerokość barków, kolana idą za palcami, plecy w neutralnej pozycji. Głębokość — do równoległej lub niżej, jeśli pozwala mobilność.',
    'Присідання із вагою': 'Przysiady z obciążeniem',
    'Публікувати свої фото можна буде після входу — сервер спільноти ще підключається. Поки тут дописи Gym Log і приклади профілів.': 'Publikowanie własnych zdjęć będzie możliwe po zalogowaniu — serwer społeczności jest jeszcze w trakcie podłączania. Na razie są tu wpisy Gym Log i przykładowe profile.',
    'Після тренування — 10 хвилин мобільності для стегон і грудного відділу.': 'Po treningu — 10 minut mobilności dla bioder i odcinka piersiowego.',
    'Ранкова жіноча група — техніка румунської тяги 🙌': 'Poranna grupa kobiet — technika rumuńskiego martwego ciągu 🙌',
