    'Субота — функціональне коло: гирі, канати, скакалка 🔥': 'Sobota — obwód funkcjonalny: kettlebelle, liny, skakanka 🔥',
    'Так виглядатимуть сторінки тренерів і атлетів. Приклади зникнуть, коли зареєструються справжні люди.': 'Tak będą wyglądać strony trenerów i atletów. Przykłady znikną, gdy zarejestrują się prawdziwi ludzie.',
    'Так може виглядати профіль тренера: силові, 8 років досвіду, ранкові групи 💪': 'Tak może wyglądać profil trenera: siłowe, 8 lat doświadczenia, poranne grupy 💪',
