    'Окрема програма на одну річ: качаєш її до цілі за рівнями й днями. Ваги тут немає — росте кількість повторень.': 'Ein eigenes Programm für eine Sache: du trainierst sie über Level und Tage bis zum Ziel. Kein Gewicht — die Wiederholungen wachsen.',
    'Рівень — 3 заняття. Обсяг росте на ~7% за заняття, кожен 4-й рівень легший (розгрузка), кожні 2 рівні — новий тест максимуму. Не закрив день — наступного разу повторюєш його.': 'Ein Level sind 3 Einheiten. Das Volumen wächst ~7% pro Einheit, jedes 4. Level ist leichter (Deload), alle 2 Level ein neuer Maximaltest. Tag nicht geschafft — du wiederholst ihn nächstes Mal.',
