    'Встав ключ OpenAI (ChatGPT) з platform.openai.com/api-keys — потрібен невеликий баланс на API, фото коштує копійки. Або безкоштовний ключ Google Gemini з aistudio.google.com/apikey. Застосунок сам розпізнає, який це ключ; зберігається він лише на цьому пристрої.': 'Füge einen OpenAI-Schlüssel (ChatGPT) von platform.openai.com/api-keys ein — braucht ein kleines API-Guthaben, ein Foto kostet Centbruchteile. Oder einen kostenlosen Google-Gemini-Schlüssel von aistudio.google.com/apikey. Die App erkennt den Schlüsseltyp automatisch; er bleibt nur auf diesem Gerät.',
