    'Тема': 'Thema',
    'Вкажи пошту акаунта. Дані на телефоні стираються в Налаштуваннях → «Стерти всі дані»; дані на сервері (профіль, дописи, повідомлення) видалимо за твоїм зверненням.': 'Gib die E-Mail deines Kontos an. Daten auf dem Telefon löschst du unter Einstellungen → „Alle Daten löschen“; Daten auf dem Server (Profil, Beiträge, Nachrichten) löschen wir auf deine Anfrage.',
