    'Перед новою програмою порадься з лікарем, якщо маєш проблеми зі спиною, суглобами чи серцем. Вагу додавай лише з чистою технікою.': 'Sprich vor einem neuen Programm mit deinem Arzt, wenn du Probleme mit dem Rücken, den Gelenken oder dem Herzen hast. Steigere das Gewicht nur bei sauberer Technik.',
