    'Велике навантаження: більше підходів і важчі вправи. Для тих, хто пройшов середній рівень.': 'Hohe Belastung: mehr Sätze und schwerere Übungen. Für alle, die die mittlere Stufe geschafft haben.',
    'Пн, Ср, Пт — повне тренування; в інші дні — легке, як на середньому рівні.': 'Mo, Mi, Fr – volles Training; an den anderen Tagen – leicht, wie auf der mittleren Stufe.',
    'Зворотні скручування — з прямими ногами. Віджимання — з ногами на стільці.': 'Reverse Crunches – mit gestreckten Beinen. Liegestütze – mit den Füßen auf dem Stuhl.',
