    'Готування': 'Kochen',
    'Проста страва з твоїх продуктів: білок, гарнір і овочі. Готуй усе паралельно — кроки йдуть від найдовшого.': 'Ein einfaches Gericht aus deinen Produkten: Eiweiß, Beilage und Gemüse. Koche alles parallel — die Schritte gehen vom längsten aus.',
