    'Gym Log не лікар і не підказує, що, скільки й як приймати. Це лише твій нагадувач: дозування, курс і уколи — тільки за призначенням лікаря.': 'Gym Log ist kein Arzt und gibt keine Empfehlung, was, wie viel und wie du etwas einnehmen sollst. Es ist nur deine Erinnerung: Dosierung, Kur und Spritzen — nur nach ärztlicher Verordnung.',
