    'Скільки в середньому додавав результат після паузи в N днів. Зелене — твій найкращий інтервал.': 'Um wie viel dein Ergebnis im Schnitt nach N Tagen Pause stieg. Grün ist dein bestes Intervall.',
    'Рахується на пристрої: для кожної вправи беруться сусідні тренування — розрив у днях і зміна найкращого підходу (1ПМ або повторення). Значення усереднюються по групі мʼязів. Потрібно щонайменше {min} пари, інакше показується типова пауза {gap}.': 'Wird auf dem Gerät berechnet: Für jede Übung werden benachbarte Trainings verglichen — der Abstand in Tagen und die Änderung des besten Satzes (1RM oder Wiederholungen). Die Werte werden pro Muskelgruppe gemittelt. Es werden mindestens {min} Paare benötigt, sonst wird die typische Pause von {gap} angezeigt.',
