    'Сервер ще не підключено': 'Server noch nicht verbunden',
    'Кабінет тренера — це записи клієнтів, призначення тренувань і контроль прогресу. Для цього потрібен безкоштовний сервер.': 'Der Trainerbereich umfasst Kundenbuchungen, Trainingszuweisungen und Fortschrittskontrolle. Dafür wird ein kostenloser Server benötigt.',
    'Власнику: створи проєкт за інструкцією <b>backend/SUPABASE_SETUP.md</b> (на ПК) і надішли Claude два рядки — Project URL і anon-ключ. Після цього тут з\'явиться вхід.': 'Für den Besitzer: Erstelle ein Projekt nach der Anleitung <b>backend/SUPABASE_SETUP.md</b> (am PC) und sende Claude zwei Zeilen — Project URL und anon-Schlüssel. Danach erscheint hier die Anmeldung.',
