    'Сервер аналізу ще не налаштований — додай свій ключ через 🔑': 'El servidor de análisis aún no está configurado — añade tu propia clave con 🔑',
    'Це не схоже на ключ OpenAI (sk-…) чи Gemini (AIza…) — перевір, звідки ти його скопіював': 'No parece una clave de OpenAI (sk-…) ni de Gemini (AIza…) — revisa de dónde la copiaste',
    'Ключ API (ChatGPT або Gemini)': 'Clave API (ChatGPT o Gemini)',
    'Встав ключ OpenAI (ChatGPT) з platform.openai.com/api-keys — потрібен невеликий баланс на API, фото коштує копійки. Або безкоштовний ключ Google Gemini з aistudio.google.com/apikey. Застосунок сам розпізнає, який це ключ; зберігається він лише на цьому пристрої.': 'Pega una clave de OpenAI (ChatGPT) de platform.openai.com/api-keys — requiere un pequeño saldo de API, una foto cuesta céntimos. O una clave gratuita de Google Gemini de aistudio.google.com/apikey. La app detecta el tipo de clave automáticamente; se guarda solo en este dispositivo.',
