    'Дякуємо! Скаргу надіслано': '¡Gracias! Denuncia enviada',
    'Заблокувати? Ви не бачитимете дописів і повідомлень одне одного.': '¿Bloquear? No veréis las publicaciones ni los mensajes del otro.',
