    'досвідчений': 'avanzado',
    'Велике навантаження: більше підходів і важчі вправи. Для тих, хто пройшов середній рівень.': 'Carga alta: más series y ejercicios más duros. Para quienes han superado el nivel intermedio.',
    'Пн, Ср, Пт — повне тренування; в інші дні — легке, як на середньому рівні.': 'Lun, mié, vie: entrenamiento completo; los demás días, ligero, como en el nivel intermedio.',
    'Зворотні скручування — з прямими ногами. Віджимання — з ногами на стільці.': 'Crunch inverso: con las piernas estiradas. Flexiones: con los pies sobre una silla.',
