    'Готування': 'Cocinar',
    'Проста страва з твоїх продуктів: білок, гарнір і овочі. Готуй усе паралельно — кроки йдуть від найдовшого.': 'Un plato sencillo con tus productos: proteína, guarnición y verduras. Cocina todo en paralelo — los pasos van del más largo al más corto.',
