    'Не медична порада': 'No es consejo médico',
    'Gym Log не лікар і не підказує, що, скільки й як приймати. Це лише твій нагадувач: дозування, курс і уколи — тільки за призначенням лікаря.': 'Gym Log no es un médico y no te dice qué tomar, cuánto ni cómo. Es solo tu recordatorio: dosis, ciclo e inyecciones — únicamente según la prescripción de tu médico.',
