    'Виклади все в тарілку: білок, гарнір і овочі поруч': 'Pon todo en el plato: proteína, guarnición y verduras juntas',
    'Запечи {x} в духовці при 200 °C 20–25 хв (або обсмаж на сковороді по 6–7 хв з кожного боку) — сік має бути прозорим': 'Hornea {x} a 200 °C durante 20–25 min (o fríe en sartén 6–7 min por cada lado) — el jugo debe salir transparente',
    'Опусти {x} в киплячу воду на 9 хв, потім на 2 хв у холодну — легше почистити': 'Sumerge {x} en agua hirviendo 9 min y luego 2 min en agua fría — se pela más fácil',
    'Виклади {x} в тарілку — готувати не треба': 'Pon {x} en el plato — no hace falta cocinar',
    'Відкрий {x}, злий рідину й розбери виделкою': 'Abre {x}, escurre el líquido y desmenuza con un tenedor',
    'Запечи {x} в духовці при 200 °C 12–15 хв шкірою донизу': 'Hornea {x} a 200 °C durante 12–15 min con la piel hacia abajo',
