    'Консервовану {x} промий і прогрій 3–5 хв (суху — замочи на ніч і вари 60–90 хв)': '{x} de lata: enjuaga y calienta 3–5 min (seco: déjalo en remojo toda la noche y cuece 60–90 min)',
    'Консервований {x} промий і прогрій 3–5 хв (сухий — замочи на ніч і вари 60–90 хв)': '{x} de lata: enjuaga y calienta 3–5 min (seco: déjalo en remojo toda la noche y cuece 60–90 min)',
    'Промий {x}, залий водою 1:2, доведи до кипіння й вари під кришкою на слабкому вогні 15–18 хв': 'Enjuaga {x}, cubre con agua en proporción 1:2, lleva a ebullición y cuece tapado a fuego lento 15–18 min',
    'Промий {x}, залий водою 1:2 і вари під кришкою на слабкому вогні 15–20 хв': 'Enjuaga {x}, cubre con agua en proporción 1:2 y cuece tapado a fuego lento 15–20 min',
    'Вари {x} в киплячій підсоленій воді 8–10 хв (як на пачці) і злий воду': 'Hierve {x} en agua con sal hirviendo 8–10 min (como indica el envase) y escurre',
    'Почисть {x}, наріж частками й запечи при 200 °C 30–35 хв (або звари в підсоленій воді 20 хв)': 'Pela {x}, corta en gajos y hornea a 200 °C 30–35 min (o hierve en agua con sal 20 min)',
    'Залий {x} водою 1:2 і вари під кришкою 12–15 хв': 'Cubre {x} con agua en proporción 1:2 y cuece tapado 12–15 min',
    'Залий {x} окропом 1:1, накрий на 5 хв і розпуши виделкою': 'Cubre {x} con agua hirviendo en proporción 1:1, tapa 5 min y suelta con un tenedor',
    'Промий {x}, залий водою 1:3 і вари 25–40 хв до м\'якості': 'Enjuaga {x}, cubre con agua en proporción 1:3 y cuece 25–40 min hasta que esté tierno',
