    'Офіційний акаунт Gym Log: техніка вправ, відновлення, прості плани для залу й дому.': 'Cuenta oficial de Gym Log: técnica de ejercicios, recuperación y planes sencillos para el gimnasio y la casa.',
    'Офіційні акаунти': 'Cuentas oficiales',
    'Планка: тіло — одна лінія, сідниці напружені, дихай рівно. Краще 3×30 с правильно, ніж 2 хв із провисанням.': 'Plancha: cuerpo en una línea, glúteos apretados, respira con calma. Mejor 3×30 s bien hechos que 2 min con la cadera caída.',
    'Приклад профілю': 'Perfil de ejemplo',
    'Приклад профілю атлета: пауерліфтинг-аматор, станова — моя любов.': 'Perfil de ejemplo de atleta: powerlifter aficionado, el peso muerto es mi pasión.',
    'Приклад профілю атлета: пів року в залі, ціль — присід 70 кг.': 'Perfil de ejemplo de atleta: medio año en el gimnasio, objetivo: sentadilla de 70 kg.',
    'Приклад профілю тренерки: жіночі групи, техніка з нуля, без страху перед залізом 🙌': 'Perfil de ejemplo de entrenadora: grupos de mujeres, técnica desde cero, sin miedo a las pesas 🙌',
    'Приклад профілю — так виглядатиме сторінка справжньої людини': 'Perfil de ejemplo: así se verá la página de una persona real',
    'Приклад профілю: мобільність, розтяжка, відновлення після травм.': 'Perfil de ejemplo: movilidad, estiramientos, recuperación tras lesiones.',
    'Приклад профілю: функціональний тренінг і кросфіт, перше заняття безкоштовно 🔥': 'Perfil de ejemplo: entrenamiento funcional y CrossFit, primera sesión gratis 🔥',
    'Приклади профілів': 'Perfiles de ejemplo',
    'Присід: стопи на ширині плечей, коліна йдуть за носками, спина нейтральна. Глибина — до паралелі або нижче, якщо дозволяє мобільність.': 'Sentadilla: pies al ancho de los hombros, rodillas en línea con las puntas, espalda neutra. Profundidad: hasta paralelo o más si tu movilidad lo permite.',
    'Присідання із вагою': 'Sentadillas con peso',
    'Публікувати свої фото можна буде після входу — сервер спільноти ще підключається. Поки тут дописи Gym Log і приклади профілів.': 'Podrás publicar tus fotos después de iniciar sesión: el servidor de la comunidad aún se está conectando. Por ahora, aquí tienes publicaciones de Gym Log y perfiles de ejemplo.',
    'Після тренування — 10 хвилин мобільності для стегон і грудного відділу.': 'Después de entrenar: 10 minutos de movilidad para las caderas y la zona torácica.',
    'Ранкова жіноча група — техніка румунської тяги 🙌': 'Grupo de mujeres por la mañana: técnica del peso muerto rumano 🙌',
    'Скопійовано': 'Copiado',
    'Станова тяга': 'Peso muerto',
    'Стежити': 'Seguir',
    "Стрічка підписок з’явиться разом із сервером спільноти": 'El feed de seguidos aparecerá junto con el servidor de la comunidad',
    'Субота — функціональне коло: гирі, канати, скакалка 🔥': 'Sábado: circuito funcional con pesas rusas, cuerdas y comba 🔥',
    'Так виглядатимуть сторінки тренерів і атлетів. Приклади зникнуть, коли зареєструються справжні люди.': 'Así se verán las páginas de entrenadores y atletas. Los ejemplos desaparecerán cuando se registren personas reales.',
    'Так може виглядати профіль тренера: силові, 8 років досвіду, ранкові групи 💪': 'Así podría verse el perfil de un entrenador: fuerza, 8 años de experiencia, grupos por la mañana 💪',
