    'Скільки в середньому додавав результат після паузи в N днів. Зелене — твій найкращий інтервал.': 'Cuánto mejoraba en promedio tu resultado tras una pausa de N días. El verde es tu mejor intervalo.',
    'Рахується на пристрої: для кожної вправи беруться сусідні тренування — розрив у днях і зміна найкращого підходу (1ПМ або повторення). Значення усереднюються по групі мʼязів. Потрібно щонайменше {min} пари, інакше показується типова пауза {gap}.': 'Se calcula en el dispositivo: para cada ejercicio se comparan entrenamientos contiguos: el intervalo en días y el cambio de la mejor serie (1RM o repeticiones). Los valores se promedian por grupo muscular. Se necesitan al menos {min} pares; si no, se muestra la pausa típica de {gap}.',
