    'Вкажи пошту акаунта. Дані на телефоні стираються в Налаштуваннях → «Стерти всі дані»; дані на сервері (профіль, дописи, повідомлення) видалимо за твоїм зверненням.': 'Indique l’e-mail de ton compte. Les données du téléphone s’effacent dans Réglages → « Effacer toutes les données » ; celles du serveur (profil, publications, messages) seront supprimées sur ta demande.',
