    'Як займатися': 'Comment s\'entraîner',
    'Перед новою програмою порадься з лікарем, якщо маєш проблеми зі спиною, суглобами чи серцем. Вагу додавай лише з чистою технікою.': 'Avant de commencer un nouveau programme, consulte ton médecin si tu as des problèmes de dos, d\'articulations ou de cœur. N\'augmente la charge qu\'avec une technique propre.',
    'Додати в мої тренування': 'Ajouter à mes séances',
    'Поставити програму в тижневий план? Дні тижня заміняться днями програми.': 'Mettre le programme dans le plan hebdomadaire ? Les jours de la semaine seront remplacés par ceux du programme.',
    'Програму додано — дивись «Календар»': 'Programme ajouté — regarde le « Calendrier »',
    'Приклади й заготовки': 'Exemples et modèles',
    'Поширені схеми вітамінів і заготовки розкладу: гірка, через день, прийом і перерва': 'Schémas courants de vitamines et modèles de planning : pyramide, un jour sur deux, prise et pause',
    'Перш ніж приймати — до лікаря': 'Avant d\'en prendre, vois un médecin',
    'Це приклади поширених схем із книг про тренування, а не призначення. Дози, протипоказання й поєднання з ліками перевір з лікарем. Після створення курсу все можна змінити.': 'Ce sont des exemples de schémas courants tirés de livres d\'entraînement, pas des prescriptions. Vérifie les doses, contre-indications et associations avec des médicaments auprès de ton médecin. Une fois la cure créée, tout peut être modifié.',
    'Приклади курсів': 'Exemples de cures',
    'приклад — дози узгодь з лікарем': 'exemple — vois les doses avec ton médecin',
    'Заготовки розкладу': 'Modèles de planning',
    'Лише форма курсу — без назв і доз. Назву й дози впишеш сам за призначенням.': 'Seulement la forme de la cure, sans noms ni doses. Tu saisis toi-même le nom et les doses selon la prescription.',
