    'Базовий набір на кожен день': 'Base quotidienne',
    'Мультивітаміни, омега-3, D3 з кальцієм, C, E і коензим Q10 — щодня після їжі.': 'Multivitamines, oméga-3, D3 avec calcium, C, E et coenzyme Q10 — chaque jour après le repas.',
    'По 1 капсулі після сніданку й після обіду.': '1 gélule après le petit-déjeuner et après le déjeuner.',
