    "Їжа на 3 дні за годину: крупа, запечене м’ясо, овочі. Рецепти з калоріями — у розділі «Рецепти».": 'Repas pour 3 jours en une heure : céréales, viande rôtie, légumes. Recettes avec calories dans la section « Recettes ».',
    'Андрій': 'Andrii',
    'Атлет': 'Athlète',
    'Вода: 30–35 мл на кг ваги, у дні тренувань більше. Спрага — вже запізнення.': "Eau : 30–35 ml par kg de poids, plus les jours d'entraînement. La soif, c'est déjà trop tard.",
    'Відкрити рецепти': 'Ouvrir les recettes',
    'Відпочинок між підходами: 1–2 хв на легкі вправи, 2–4 хв на важкі базові. Таймер у застосунку підкаже сам.': "Repos entre les séries : 1–2 min pour les exercices légers, 2–4 min pour les gros mouvements de base. Le minuteur de l'appli s'en charge.",
    'Вінниця': 'Vinnytsia',
    'Гантелі, гумки й килимок — цього досить для повноцінного тренування вдома.': 'Haltères, élastiques et un tapis : cela suffit pour une vraie séance à la maison.',
