    'Офіційний акаунт Gym Log: 100 рецептів з калоріями й БЖВ — у розділі «Рецепти».': 'Compte officiel Gym Log : 100 recettes avec calories et macros dans la section « Recettes ».',
    'Офіційний акаунт Gym Log: техніка вправ, відновлення, прості плани для залу й дому.': 'Compte officiel Gym Log : technique des exercices, récupération, programmes simples pour la salle et la maison.',
    'Офіційні акаунти': 'Comptes officiels',
    'Планка: тіло — одна лінія, сідниці напружені, дихай рівно. Краще 3×30 с правильно, ніж 2 хв із провисанням.': 'Planche : corps aligné, fessiers contractés, respire calmement. Mieux vaut 3×30 s bien faites que 2 min avec le dos creusé.',
