    'Приклад профілю атлета: пауерліфтинг-аматор, станова — моя любов.': "Exemple de profil d'athlète : powerlifter amateur, le soulevé de terre, c'est mon truc.",
    'Приклад профілю атлета: пів року в залі, ціль — присід 70 кг.': "Exemple de profil d'athlète : six mois en salle, objectif — squat à 70 kg.",
    'Приклад профілю тренерки: жіночі групи, техніка з нуля, без страху перед залізом 🙌': 'Exemple de profil de coach : groupes de femmes, technique depuis zéro, sans peur de la fonte 🙌',
    'Приклад профілю — так виглядатиме сторінка справжньої людини': "Exemple de profil — voici à quoi ressemblera la page d'une vraie personne",
    'Приклад профілю: мобільність, розтяжка, відновлення після травм.': 'Exemple de profil : mobilité, étirements, récupération après blessure.',
    'Приклад профілю: функціональний тренінг і кросфіт, перше заняття безкоштовно 🔥': 'Exemple de profil : entraînement fonctionnel et CrossFit, première séance offerte 🔥',
    'Приклади профілів': 'Exemples de profils',
    'Присід: стопи на ширині плечей, коліна йдуть за носками, спина нейтральна. Глибина — до паралелі або нижче, якщо дозволяє мобільність.': "Squat : pieds à largeur d'épaules, genoux dans l'axe des orteils, dos neutre. Profondeur — jusqu'à la parallèle ou plus bas si la mobilité le permet.",
    'Присідання із вагою': 'Squats lestés',
    'Публікувати свої фото можна буде після входу — сервер спільноти ще підключається. Поки тут дописи Gym Log і приклади профілів.': "Tu pourras publier tes photos après la connexion — le serveur de la communauté est encore en cours de branchement. Pour l'instant, retrouve ici les publications de Gym Log et des exemples de profils.",
