    'Окрема програма на одну річ: качаєш її до цілі за рівнями й днями. Ваги тут немає — росте кількість повторень.': 'Un programma a parte per una cosa sola: la alleni fino all\'obiettivo per livelli e giorni. Qui non c\'è peso — crescono le ripetizioni.',
    'Рівень — 3 заняття. Обсяг росте на ~7% за заняття, кожен 4-й рівень легший (розгрузка), кожні 2 рівні — новий тест максимуму. Не закрив день — наступного разу повторюєш його.': 'Un livello sono 3 sessioni. Il volume cresce del ~7% per sessione, ogni 4° livello è più leggero (scarico), ogni 2 livelli un nuovo test del massimo. Giorno non chiuso — lo ripeti la prossima volta.',
