    'Встав ключ OpenAI (ChatGPT) з platform.openai.com/api-keys — потрібен невеликий баланс на API, фото коштує копійки. Або безкоштовний ключ Google Gemini з aistudio.google.com/apikey. Застосунок сам розпізнає, який це ключ; зберігається він лише на цьому пристрої.': 'Incolla una chiave OpenAI (ChatGPT) da platform.openai.com/api-keys — serve un piccolo saldo API, una foto costa centesimi. Oppure una chiave gratuita Google Gemini da aistudio.google.com/apikey. L’app riconosce il tipo di chiave automaticamente; resta solo su questo dispositivo.',
