    'Велике навантаження: більше підходів і важчі вправи. Для тих, хто пройшов середній рівень.': 'Carico elevato: più serie ed esercizi più difficili. Per chi ha completato il livello intermedio.',
    'Пн, Ср, Пт — повне тренування; в інші дні — легке, як на середньому рівні.': 'Lun, mer, ven: allenamento completo; negli altri giorni leggero, come nel livello intermedio.',
