    'Не медична порада': 'Non è un consiglio medico',
    'Gym Log не лікар і не підказує, що, скільки й як приймати. Це лише твій нагадувач: дозування, курс і уколи — тільки за призначенням лікаря.': 'Gym Log non è un medico e non suggerisce cosa, quanto e come assumere. È solo il tuo promemoria: dosaggio, ciclo e iniezioni — solo secondo la prescrizione del medico.',
