    'Записуй лише те, що призначив лікар. Gym Log не перевіряє дози й сумісність препаратів.': 'Annota solo ciò che ti ha prescritto il medico. Gym Log non controlla i dosaggi né la compatibilità dei farmaci.',
    'Впиши назву': 'Inserisci un nome',
    'Видалити «{x}» разом з відмітками прийому?': 'Eliminare «{x}» insieme ai segni di assunzione?',
    'Овочі посоли, поперчи й полий ложкою олії': 'Sala e pepa le verdure e condiscile con un cucchiaio d\'olio',
    'Виклади все в тарілку: білок, гарнір і овочі поруч': 'Metti tutto nel piatto: proteine, contorno e verdure vicini',
    'Запечи {x} в духовці при 200 °C 20–25 хв (або обсмаж на сковороді по 6–7 хв з кожного боку) — сік має бути прозорим': 'Cuoci {x} in forno a 200 °C per 20–25 min (oppure in padella 6–7 min per lato) — il succo deve essere limpido',
    'Опусти {x} в киплячу воду на 9 хв, потім на 2 хв у холодну — легше почистити': 'Immergi {x} in acqua bollente per 9 min, poi 2 min in acqua fredda — si pela più facilmente',
    'Виклади {x} в тарілку — готувати не треба': 'Metti {x} nel piatto — non serve cuocere',
    'Відкрий {x}, злий рідину й розбери виделкою': 'Apri {x}, scola il liquido e sfilaccia con una forchetta',
    'Запечи {x} в духовці при 200 °C 12–15 хв шкірою донизу': 'Cuoci {x} in forno a 200 °C per 12–15 min con la pelle verso il basso',
    'Запечи {x} в духовці при 200 °C 15–20 хв (або обсмаж по 4 хв з кожного боку)': 'Cuoci {x} in forno a 200 °C per 15–20 min (oppure in padella 4 min per lato)',
    'Наріж {x} шматочками, обсмаж 5 хв і тушкуй під кришкою 40–45 хв, підливаючи воду': 'Taglia {x} a pezzi, rosola 5 min e fai stufare col coperchio 40–45 min, aggiungendo acqua se serve',
    'Наріж {x} і обсмаж на сковороді 15–20 хв до золотистої скоринки': 'Taglia {x} e cuoci in padella 15–20 min fino a doratura',
    'Обсмаж {x} на сковороді 10–12 хв, розбиваючи грудочки': 'Rosola {x} in padella 10–12 min, schiacciando i grumi',
    'Консервовану {x} промий і прогрій 3–5 хв (суху — замочи на ніч і вари 60–90 хв)': '{x} in scatola: sciacqua e scalda 3–5 min (secco: lascia in ammollo per una notte e cuoci 60–90 min)',
    'Консервований {x} промий і прогрій 3–5 хв (сухий — замочи на ніч і вари 60–90 хв)': '{x} in scatola: sciacqua e scalda 3–5 min (secco: lascia in ammollo per una notte e cuoci 60–90 min)',
    'Промий {x}, залий водою 1:2, доведи до кипіння й вари під кришкою на слабкому вогні 15–18 хв': 'Sciacqua {x}, copri con acqua in proporzione 1:2, porta a ebollizione e cuoci col coperchio a fuoco basso 15–18 min',
    'Промий {x}, залий водою 1:2 і вари під кришкою на слабкому вогні 15–20 хв': 'Sciacqua {x}, copri con acqua in proporzione 1:2 e cuoci col coperchio a fuoco basso 15–20 min',
    'Вари {x} в киплячій підсоленій воді 8–10 хв (як на пачці) і злий воду': 'Lessa {x} in acqua bollente salata 8–10 min (come indicato sulla confezione) e scola',
    'Почисть {x}, наріж частками й запечи при 200 °C 30–35 хв (або звари в підсоленій воді 20 хв)': 'Pela {x}, taglia a spicchi e cuoci in forno a 200 °C 30–35 min (oppure lessa in acqua salata 20 min)',
    'Залий {x} водою 1:2 і вари під кришкою 12–15 хв': 'Copri {x} con acqua in proporzione 1:2 e cuoci col coperchio 12–15 min',
    'Залий {x} окропом 1:1, накрий на 5 хв і розпуши виделкою': 'Versa acqua bollente su {x} in proporzione 1:1, copri per 5 min e sgrana con una forchetta',
    'Промий {x}, залий водою 1:3 і вари 25–40 хв до м\'якості': 'Sciacqua {x}, copri con acqua in proporzione 1:3 e cuoci 25–40 min fino a renderlo morbido',
    'Наріж {x} скибками; можна підсушити в тостері 2–3 хв': 'Taglia {x} a fette; puoi tostare nel tostapane 2–3 min',
    'Тонко нашаткуй {x} і пом\'ни руками з дрібкою солі — стане соковитішою': 'Affetta finemente {x} e impasta con le mani con un pizzico di sale — il risultato sarà più succoso',
