    'Планка: тіло — одна лінія, сідниці напружені, дихай рівно. Краще 3×30 с правильно, ніж 2 хв із провисанням.': 'Plank: corpo in linea, glutei contratti, respira con regolarità. Meglio 3×30 s fatti bene che 2 min con il bacino che cede.',
