    'Присід: стопи на ширині плечей, коліна йдуть за носками, спина нейтральна. Глибина — до паралелі або нижче, якщо дозволяє мобільність.': 'Squat: piedi alla larghezza delle spalle, ginocchia in linea con le punte, schiena neutra. Profondità: fino al parallelo o più giù se la mobilità lo consente.',
    'Присідання із вагою': 'Squat con sovraccarico',
    'Публікувати свої фото можна буде після входу — сервер спільноти ще підключається. Поки тут дописи Gym Log і приклади профілів.': "Potrai pubblicare le tue foto dopo l'accesso: il server della community si sta ancora collegando. Per ora qui trovi i post di Gym Log e profili di esempio.",
