    'Скільки в середньому додавав результат після паузи в N днів. Зелене — твій найкращий інтервал.': 'Di quanto migliorava in media il tuo risultato dopo una pausa di N giorni. Il verde è il tuo intervallo migliore.',
    'Рахується на пристрої: для кожної вправи беруться сусідні тренування — розрив у днях і зміна найкращого підходу (1ПМ або повторення). Значення усереднюються по групі мʼязів. Потрібно щонайменше {min} пари, інакше показується типова пауза {gap}.': 'Calcolato sul dispositivo: per ogni esercizio si confrontano gli allenamenti vicini — l\'intervallo in giorni e la variazione della serie migliore (1RM o ripetizioni). I valori sono mediati per gruppo muscolare. Servono almeno {min} coppie, altrimenti viene mostrata la pausa tipica di {gap}.',
