    'Кабінет тренера — це записи клієнтів, призначення тренувань і контроль прогресу. Для цього потрібен безкоштовний сервер.': 'L\'area allenatore gestisce le prenotazioni dei clienti, l\'assegnazione degli allenamenti e il controllo dei progressi. Serve un server gratuito.',
